def apply(inputs, premises):
    answer = {}
    for name in inputs["asset_names"]:
        answer[str(name)] = []
    count = min(len(inputs["claim_asset_indexes"]), len(inputs["claim_citations"]), len(inputs["claim_limits"]))
    for j in range(count):
        asset_index = int(inputs["claim_asset_indexes"][j])
        if asset_index >= 0 and asset_index < len(inputs["asset_names"]):
            name = str(inputs["asset_names"][asset_index])
            citation = str(inputs["claim_citations"][j])
            if inputs["output_family"] == "EC":
                if citation not in answer[name]:
                    answer[name] = answer[name] + [citation]
            if inputs["output_family"] == "EV":
                claim_value = min(float(inputs["asset_values"][asset_index]), float(inputs["claim_limits"][j]))
                answer[name] = answer[name] + [{"citation": citation, "claim_value": claim_value}]
    return {"answer": answer}

def apply(inputs, premises):
    total = int(inputs["ticket_price"])
    count = min(len(inputs["bag_base_fees"]), len(inputs["bag_overweight_fees"]), len(inputs["bag_oversize_fees"]))
    for i in range(count):
        base_fee = int(inputs["bag_base_fees"][i])
        overweight_fee = int(inputs["bag_overweight_fees"][i])
        oversize_fee = int(inputs["bag_oversize_fees"][i])
        excess_fee = overweight_fee + oversize_fee
        if premises["simultaneous_excess_rule"] == "higher_only":
            excess_fee = max(overweight_fee, oversize_fee)
        total = total + base_fee + excess_fee
    return {"answer": int(total)}
